def _domain_pillars(trim):
    pillars = []
    for pillar in trim["chart"]["pillars"]:
        pillars.append({
            "name": pillar["name"],
            "ganzhi": pillar["ganzhi"],
            "stem": {"value": pillar["stem"]["value"],
                     "ten_god": pillar["stem"]["ten_god"]},
            "branch": {
                "value": pillar["branch"]["value"],
                "hidden_stems": [
                    {"stem": entry["stem"]}
                    for entry in pillar["branch"]["hidden_stems"]],
            },
        })
    return pillars


