def _jieqi_neighbours(utc_instant):
    """(previous, next) jieqi from the pinned provider, as the backend
    module reads them: Shanghai wall clock, provider solar times."""
    shanghai = utc_instant.astimezone(timezone(timedelta(hours=8)))
    lunar = Solar.fromYmdHms(
        shanghai.year, shanghai.month, shanghai.day,
        shanghai.hour, shanghai.minute, shanghai.second).getLunar()
    out = []
    for term in (lunar.getPrevJieQi(False), lunar.getNextJieQi()):
        wall = datetime.strptime(term.getSolar().toYmdHms(),
                                 "%Y-%m-%d %H:%M:%S")
        out.append((term.getName(),
                    wall.replace(tzinfo=timezone(timedelta(hours=8)))
                    .astimezone(timezone.utc)))
    return out


def _nearest_lichun(utc_instant):
    shanghai_year = utc_instant.astimezone(
        timezone(timedelta(hours=8))).year
    found = {}
    for year in (shanghai_year - 1, shanghai_year, shanghai_year + 1):
        lunar = Solar.fromYmdHms(year, 2, 4, 12, 0, 0).getLunar()
        for term in (lunar.getPrevJieQi(False), lunar.getNextJieQi()):
            if term.getName() == "立春":
                wall = datetime.strptime(term.getSolar().toYmdHms(),
                                         "%Y-%m-%d %H:%M:%S")
                moment = wall.replace(
                    tzinfo=timezone(timedelta(hours=8))).astimezone(
                        timezone.utc)
                found[moment.isoformat()] = moment
    return sorted(found.values())


def build_true_solar():
    instant = datetime.fromisoformat(BIRTH)
    conversion = apparent_solar_time(instant, LONGITUDE, 8)
    apparent = conversion["apparent_solar_time"]
    utc_instant = instant.astimezone(timezone.utc)

    neighbours = dict(_jieqi_neighbours(utc_instant))
    nearest_term, nearest_minutes, nearest_signed = None, None, None
    for name, moment in neighbours.items():
        signed = (moment - utc_instant).total_seconds() / 60.0
        if nearest_minutes is None or abs(signed) < nearest_minutes:
            nearest_minutes = abs(signed)
            nearest_signed = signed
            nearest_term = name
    within_budget = nearest_minutes < 2.0

    lichun_list = _nearest_lichun(utc_instant)
    nearest_lichun, nearest_lichun_signed = None, None
    for moment in lichun_list:
        signed = (utc_instant - moment).total_seconds() / 60.0
        if nearest_lichun_signed is None \
                or abs(signed) < abs(nearest_lichun_signed):
            nearest_lichun = moment
            nearest_lichun_signed = signed

    trim = _earth_tomb_trim()
    pillars = _domain_pillars(trim)
    day_master = {"stem": "戊", "element": "土", "polarity": "阳"}

    def iso(value):
        return value.isoformat() if hasattr(value, "isoformat") else value

    conversion_json = {
        key: (iso(value) if isinstance(value, datetime) else value)
        for key, value in conversion.items()
        if key not in ("method", "astronomical_basis", "calendar_basis",
                       "precision_limits", "method_note", "julian_day")}
    conversion_json["method"] = conversion["method"]
    conversion_json["astronomical_basis"] = conversion["astronomical_basis"]

    std_wall = datetime.fromisoformat(BIRTH)
    app_wall = apparent.replace(tzinfo=None)
    # Next shichen boundary (odd hour) after each wall reading.
    def next_shichen(wall):
        base = wall.replace(minute=0, second=0, microsecond=0)
        candidate = base
        if candidate.hour % 2 == 0:
            candidate = candidate + timedelta(hours=1)
        if candidate <= wall:
            candidate = candidate + timedelta(hours=2)
        return candidate
    std_next_shichen = next_shichen(std_wall)
    app_next_shichen = next_shichen(app_wall)
    std_to_shichen = (std_next_shichen - std_wall).total_seconds() / 60.0
    app_to_shichen = (app_next_shichen - app_wall).total_seconds() / 60.0
    # Next midnight boundary after each wall reading.
    def next_midnight(wall):
        candidate = wall.replace(hour=0, minute=0, second=0,
                                 microsecond=0)
        if candidate <= wall:
            candidate = candidate + timedelta(days=1)
        return candidate
    std_to_midnight = (next_midnight(std_wall)
                       - std_wall).total_seconds() / 60.0
    app_to_midnight = (next_midnight(app_wall)
                       - app_wall).total_seconds() / 60.0

    side = "after" if nearest_lichun_signed >= 0 else "before"
    rows = []
    reasons = {
        "year": (
            "The year pillar is fixed by the true birth instant: "
            "the solar-time correction moves only the local solar "
            "reading used for the day/hour pillars, so it can never "
            "cross 立春 and the year pillar cannot change. The "
            "nearest 立春 (%s UTC) is %.1f minutes %s the true "
            "instant."
            % (nearest_lichun.isoformat(),
               abs(nearest_lichun_signed), side)),
        "month": (
            "No jieqi was crossed: the month pillar is fixed by the "
            "true birth instant, and the solar-time correction never "
            "crosses a jieqi, so the month pillar cannot change. The "
            "true instant carries the solar term 立春; the nearest "
            "boundary, %s, is %.1f minutes from the true instant."
            % (nearest_term, nearest_minutes)),
        "day": (
            "The local solar date at the birthplace (2024-02-11) "
            "matches the Shanghai date of the true instant "
            "(2024-02-11) under the midnight convention, so the day "
            "pillar is unchanged: the next 00:00 local-solar day "
            "boundary is %.1f minutes after the apparent solar time "
            "(%.1f minutes after the true instant to the next "
            "Shanghai boundary)."
            % (app_to_midnight, std_to_midnight)),
        "hour": (
            "The shichen is unchanged (申时), so the hour pillar is "
            "unchanged: the next shichen boundary (%02d:00) is %.1f "
            "minutes after the apparent solar time (%.1f minutes "
            "after the true instant in Shanghai time)."
            % (app_next_shichen.hour, app_to_shichen, std_to_shichen)),
    }
    for pillar in pillars:
        name = pillar["name"]
        rows.append({
            "name": name,
            "standard": copy.deepcopy(pillar),
            "true_solar": copy.deepcopy(pillar),
            "changed": False,
            "ten_god_reading_changed": False,
            "reason": reasons[name],
            "detail": {"governing_boundary": {
                "year": "lichun", "month": "jieqi",
                "day": "day_boundary", "hour": "shichen"}[name]},
        })

    validation = validate_tz_offset(TZ_NAME, instant, 8)
    validation["status"] = "resolved_from_tzdb"
    validation["supplied_offset_hours"] = None
    validation["supplied_offset"] = None
    validation["uncertainty"] = (
        "Offset resolved from IANA tzdb at this instant; resolution "
        "is a lookup, not proof of historical correctness (tzdb "
        "version %s)." % validation["tzdb_version"])

    return {
        "entry": "true-solar-chart-research-v1",
        "method": "modern_engineering",
        "conversion_method": conversion["method"],
        "astronomical_basis": conversion["astronomical_basis"],
        "research_only": True,
        "public": False,
        "ai": False,
        "status": "ok",
        "input": {
            "birth_local_time": BIRTH,
            "longitude_deg": LONGITUDE,
            "tz_offset_hours": 8,
            "standard_meridian_deg": 120.0,
            "day_boundary": "midnight",
            "use_true_solar_time": True,
        },
        "conversion": conversion_json,
        "standard_time_chart": {
            "pillars": pillars,
            "day_master": day_master,
            "calendar": {"local_datetime": BIRTH},
        },
        "true_solar_time_chart": {
            "pillars": copy.deepcopy(pillars),
            "day_master": copy.deepcopy(day_master),
            "calendar": {"local_datetime": iso(apparent)},
        },
        "differences": {
            "pillars": {pillar["name"]: {
                "standard": pillar["ganzhi"],
                "true_solar": pillar["ganzhi"],
                "changed": False} for pillar in pillars},
            "solar_term": {"standard": "立春", "true_solar": "立春",
                           "changed": False},
            "chart_date": {"standard": "2024-02-11",
                           "true_solar": "2024-02-11",
                           "changed": False},
            "any_pillar_changed": False,
            "month_pillar_changed": False,
            "year_pillar_changed": False,
            "day_pillar_changed": False,
            "hour_pillar_changed": False,
        },
        "jieqi": {
            "crossed": False,
            "crossed_term": None,
            "crossed_at_utc": None,
            "crossed_at_local": None,
            "minutes_from_input_to_boundary": nearest_signed,
            "standard_solar_term": "立春",
            "true_solar_solar_term": "立春",
            "nearest_boundary_term": nearest_term,
            "nearest_boundary_minutes": nearest_minutes,
            "within_precision_budget": within_budget,
            "uncertainty_window_minutes": 2.0,
            "uncertainty_window_status": "provisional",
            "uncertainty_window_adjudication": (
                "T1 (2026-11-25): 2-minute provisional research window "
                "(NOAA +/-1 min equation-of-time budget + 1 min margin); "
                "provisional, not a proven maximum error"),
            "note": (
                "The solar-time correction never crosses a jieqi: the "
                "solar term, the year pillar and the month pillar are "
                "fixed by the true birth instant on both sides. The "
                "nearest true jieqi boundary, %s, is %.1f minutes from "
                "the true input instant -- outside the provisional "
                "2-minute window (T1, 2026-11-25); the window is "
                "provisional, not a proven maximum error."
                % (nearest_term, nearest_minutes)),
        },
        "pillar_comparison": {
            "adapter": "true-solar-pillar-adapter-v1",
            "entry": "true-solar-chart-research-v1",
            "method": "modern_engineering",
            "research_only": True,
            "public": False,
            "ai": False,
            "status": "ok",
            "day_master": {"standard": day_master,
                           "true_solar": copy.deepcopy(day_master),
                           "changed": False},
            "pillars": rows,
            "year_and_month_changed_together": False,
            "month_attribution": "settled",
            "month_attribution_settled": True,
            "derived": {"branch_relations_changed": False,
                        "taohua_changed": False},
            "note": ("The day master is unchanged (戊), so the ten-god "
                     "readings are taken against the same day master on "
                     "both sides."),
            "reuse_note": ("Every stem, branch, hidden stem and ten god "
                           "above is copied verbatim from the fixture "
                           "pillars on both sides; this adapter fixture "
                           "recomputes nothing."),
        },
        "research_api": "true-solar-research-api-v1",
        "tz_validation": validation,
        "provenance": {
            "research_api": "true-solar-research-api-v1",
            "entry": "true-solar-chart-research-v1",
            "adapter": "true-solar-pillar-adapter-v1",
            "conversion_method": conversion["method"],
            "tzdb_version": tzdb_version(),
            "jieqi_window_minutes": 2.0,
            "jieqi_window_status": "provisional",
        },
        "comparison_note": (
            "The standard-time chart and the true-solar-time chart are "
            "two separate results for the same birth instant under two "
            "different, explicitly labelled conventions. Neither "
            "overwrites the other, and the standard-time chart is "
            "identical to chart_from_datetime(birth)."),
        "standard_time_convention_unchanged": True,
    }


def main():
    profile = build_profile_presentation()
    domain, scenario = build_domain_and_scenario(profile)
    (FIXTURES / "tj0427-bazi-profile-domain.json").write_text(
        json.dumps(domain, ensure_ascii=False, indent=2),
        encoding="utf-8")
    (FIXTURES / "tj0427-bazi-profile-scenario.json").write_text(
        json.dumps(scenario, ensure_ascii=False, indent=2),
        encoding="utf-8")
    (FIXTURES / "tj0427-true-solar.json").write_text(
        json.dumps(build_true_solar(), ensure_ascii=False, indent=2),
        encoding="utf-8")
    strength = [s for s in profile["sections"] if s["id"] == "strength"][0]
    fuyi = [s for s in profile["sections"]
            if s["id"] == "fuyi_research"][0]
    print("profile sections:", [s["id"] for s in profile["sections"]])
    print("modern score:", strength["research_reference"]["score"],
          "components:",
          [(c["label"], c["score"])
           for c in strength["research_reference"]["components"]])
    print("fuyi direction:",
          fuyi["research_reference"]["direction_cn"],
          "candidates:",
          fuyi["research_reference"]["candidate_stems"])
    print("fuyi formation reasons:",
          [r["note"] for r in
           fuyi["research_reference"]["formation_reasons"]])
    print("fixtures written to", FIXTURES)


if __name__ == "__main__":
    main()
